#if UNITY_EDITOR
using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
namespace FashionFit.Editor {
 public static class PoseMaterialVerification {
  [Serializable] sealed class Result {public string status="passed",scope="Editor, real garment meshes and injected two-owner grips; no physical HMD test";public int checks,exceptions,outfits,contactExports;public bool largerHatRelievesTension,fitOutsideLinearRange,independentWardrobes,threeHats,physicalDrop,headFollow,headFit,twoHandStretch,compression,hatRecovery,clothRecovery,materialContrast;public float fitStrain,fitTensionNm,hatInitialOffset,hatFinalOffset,cottonDisplacement,feltDisplacement,clothInitialError,clothFinalError;public double maximumPoseUpdateMs;}
  static Result result;static FashionFitApp app;static string folder;static void Check(bool value,string label){result.checks++;if(!value)throw new InvalidOperationException(label);}static void Log(string a,string b,LogType t){if(t==LogType.Error||t==LogType.Exception)result.exceptions++;}
  public static void RunBatch(){folder=Path.GetFullPath("Verification/PoseMaterial");Directory.CreateDirectory(folder+"/Contact");result=new Result();GameObject root=null;var mode=Physics.simulationMode;Application.logMessageReceived+=Log;
   try{Physics.simulationMode=SimulationMode.Script;root=new GameObject("Pose and material verification");app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(app,null);Check(app.Ready,app.FatalError);
    Check(app.PoseStudio.Wearables[0].Look==5&&app.PoseStudio.Wearables[1].Look==6,"Pose defaults are not dressed");int main=app.Look;var maleMaterial=app.PoseStudio.Wearables[1].Surface.Material;app.Showroom.SelectOutfitTarget(1);app.MaterialLab.SelectProfile(1);Check(app.PoseStudio.Wearables[0].Surface.Material==MembraneMaterial.Presets[1]&&app.PoseStudio.Wearables[1].Surface.Material==maleMaterial,"Changing female material also changed male");Check(!app.Wardrobe.MaterialReading.hasStiffness,"Pose material unexpectedly changed main solver");app.MaterialLab.SelectProfile(0);
    for(int target=1;target<=2;target++)for(int look=1;look<=6;look++){app.Showroom.SelectOutfitTarget(target);app.Showroom.WearLook(look);var wear=app.PoseStudio.Wearables[target-1];Check(wear.Look==look&&wear.Surface,"Pose outfit missing");Check(wear.Surface.VertexCount>500,"Pose outfit lacks detail");result.outfits++;result.maximumPoseUpdateMs=Math.Max(result.maximumPoseUpdateMs,wear.Milliseconds);Debug.Log("POSE_PHASE look="+wear.Look+" skin_ms="+wear.SkinMilliseconds+" surface_ms="+wear.SurfaceMilliseconds);Export(wear,(target==1?"Female":"Male")+look.ToString("00")+"_Neutral");}
    result.independentWardrobes=app.Look==main&&app.PoseStudio.Wearables[0].Look==6&&app.PoseStudio.Wearables[1].Look==6;Check(result.independentWardrobes,"Changing pose clothes changes main model");
    var sample=app.Showroom.Items[app.Showroom.Hats.Count+1];sample.ReturnToDisplay();sample.BeginGrip(sample.FittingPoint,Quaternion.identity);var female=app.PoseStudio.Rigs[0].Avatar;sample.transform.position=female.transform.TransformPoint(new Vector3(0,female.BodyMesh.bounds.max.y*.67f,.10f))- (sample.FittingPoint-sample.transform.position);Physics.SyncTransforms();sample.ReleaseGrip();result.physicalDrop=app.PoseStudio.Wearables[0].Look==2;Check(result.physicalDrop,"Drop near pose body did not dress it");
    for(int i=0;i<3;i++){app.Showroom.SelectOutfitTarget(i);app.Showroom.WearHat(i);}
    result.threeHats=app.Showroom.Hats[0].IsEquipped&&app.Showroom.Hats[1].IsEquipped&&app.Showroom.Hats[2].IsEquipped;Check(result.threeHats,"Equipping a pose hat removes another avatar hat");
    var head=app.PoseStudio.Rigs[0].Avatar.FindJoint("Head");var worn=app.Showroom.Hats[1];Vector3 before=head.InverseTransformPoint(worn.transform.position);head.localRotation*=Quaternion.Euler(0,30,0);result.headFollow=Vector3.Distance(before,head.InverseTransformPoint(worn.transform.position))<1e-5f;Check(result.headFollow,"Hat does not follow posed head");app.PoseStudio.ResetPose(0);
    app.Showroom.SelectOutfitTarget(2);app.Showroom.WearHat(0);var hat=app.Showroom.Hats[0];app.MaterialLab.ToggleFocus();app.MaterialLab.SelectProfile(2);Check(hat.Elastic.Material==MembraneMaterial.Presets[2]&&app.PoseStudio.Wearables[1].Surface.Material==maleMaterial,"Hat material also changed pose outfit");app.MaterialLab.SelectProfile(0);app.MaterialLab.ToggleFocus();hat.Elastic.SetSize(.80f);hat.Elastic.Step(1f/60);result.fitOutsideLinearRange=hat.Elastic.OutsideLinearRange;result.fitStrain=hat.Elastic.Reading.tensileStrain;result.fitTensionNm=hat.Elastic.Reading.tensionNm;result.headFit=result.fitStrain>.005f&&result.fitTensionNm>0;Check(result.headFit,"Head contact did not stretch undersized hat");Check(hat.Elastic.Head.Points.Length>=64,"Head support has too few measured points");hat.Elastic.SetSize(1.10f);hat.Elastic.Step(1f/60);result.largerHatRelievesTension=hat.Elastic.Reading.tensileStrain<result.fitStrain*.65f;Check(result.largerHatRelievesTension,"Larger hat did not relieve head fit tension");hat.Elastic.SetSize(.80f);hat.Elastic.Step(1f/60);
    Vector3[] fit=hat.Elastic.MeshAt(0).vertices;hat.BeginGrip(hat.FittingPoint,Quaternion.identity);Vector3[] removed=hat.Elastic.MeshAt(0).vertices;float instant=0;for(int i=0;i<fit.Length;i++)instant=Mathf.Max(instant,(fit[i]-removed[i]).magnitude);Check(instant<.001f,"Removing hat instantly resets deformation");hat.Elastic.Step(1f/60);result.hatInitialOffset=hat.Elastic.MaximumOffset;for(int i=0;i<720;i++)hat.Elastic.Step(1f/60);result.hatFinalOffset=hat.Elastic.MaximumOffset;result.hatRecovery=result.hatInitialOffset>.001f&&result.hatFinalOffset<result.hatInitialOffset*.02f;Check(result.hatRecovery,"Hat did not recover over time");hat.CancelGrip();hat.ReturnToDisplay();
    result.cottonDisplacement=ManipulateHat(hat,MembraneMaterial.Presets[0],false);result.feltDisplacement=ManipulateHat(hat,MembraneMaterial.Presets[2],false);result.materialContrast=result.cottonDisplacement>result.feltDisplacement*1.5f;Check(result.materialContrast,"Stiff material is not harder to stretch");ManipulateHat(hat,MembraneMaterial.Presets[0],true);
    app.Showroom.SelectOutfitTarget(0);app.SetLook(2);app.Wardrobe.SetMembraneMaterial(MembraneMaterial.Presets[0]);for(int i=0;i<90;i++)app.AdvanceSimulation(1f/60);
    var cloth=app.Model.GetComponentInChildren<FittingCloth>();var solver=(FittingClothSolver)typeof(FittingCloth).GetField("solver",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(cloth);Vector3[] baseline=(Vector3[])solver.Positions.Clone();int selected=15*SampleSkirtGeometry.Segments+8;Vector3 local=solver.Positions[selected],world=app.Model.transform.TransformPoint(local);Check(cloth.BeginVRGrab(0,world),"Main skirt cannot grip");
    for(int i=0;i<60;i++){cloth.MoveVRGrab(0,world+app.Model.transform.forward*.10f);app.AdvanceSimulation(1f/60);}cloth.EndVRGrab(0);result.clothInitialError=Error(solver.Positions,baseline);for(int i=0;i<360;i++)app.AdvanceSimulation(1f/60);result.clothFinalError=Error(solver.Positions,baseline);result.clothRecovery=result.clothFinalError<result.clothInitialError*.75f;Check(result.clothRecovery,"Main skirt did not recover toward pre-grip equilibrium");
    for(int g=0;g<2;g++)foreach(int look in new[]{2,5,6}){
     var wear=app.PoseStudio.Wearables[g];wear.Wear(look);var a=wear.Rig.Avatar;a.FindJoint("RightArm").localRotation*=Quaternion.Euler(0,0,-35);a.FindJoint("LeftArm").localRotation*=Quaternion.Euler(0,0,25);a.FindJoint("RightLeg").localRotation*=Quaternion.Euler(40,0,0);a.FindJoint("RightUpLeg").localRotation*=Quaternion.Euler(-25,0,0);wear.Step(1f/30);result.maximumPoseUpdateMs=Math.Max(result.maximumPoseUpdateMs,wear.Milliseconds);Debug.Log("POSE_PHASE look="+wear.Look+" skin_ms="+wear.SkinMilliseconds+" surface_ms="+wear.SurfaceMilliseconds);Export(wear,(g==0?"Female":"Male")+look.ToString("00")+"_Pose");app.PoseStudio.ResetPose(g);
    }
    for(int g=0;g<2;g++){app.PoseStudio.Wearables[g].Wear(g==0?3:6);app.Showroom.SelectOutfitTarget(g+1);app.Showroom.WearHat(g+3);}Capture("Pose_Outfits.png");
    float analytic=MembraneMaterial.Recover(.2f,1.6f,.8f);foreach(int hz in new[]{30,60,90}){float x=.2f;for(int i=0;i<hz*2;i++)x=MembraneMaterial.Recover(x,1f/hz,.8f);Check(Mathf.Abs(x-.2f*Mathf.Exp(-2/.8f))<1e-5f,"Recovery depends on frame rate");}Check(analytic>0&&analytic<.2f,"Invalid recovery function");Check(result.exceptions==0,"Unity errors");
    File.WriteAllText(folder+"/verification.json",JsonUtility.ToJson(result,true));Debug.Log("POSE_MATERIAL_OK "+JsonUtility.ToJson(result));Cleanup(root);root=null;Physics.simulationMode=mode;EditorApplication.Exit(0);
   }catch(Exception e){result.status="failed";File.WriteAllText(folder+"/verification.json",JsonUtility.ToJson(result,true));File.WriteAllText(folder+"/failure.txt",e.ToString());Debug.LogException(e);Physics.simulationMode=mode;EditorApplication.Exit(1);}finally{Application.logMessageReceived-=Log;Physics.simulationMode=mode;if(root)Cleanup(root);}
  }
  static float Error(Vector3[] a,Vector3[] b){float sum=0;for(int i=0;i<a.Length;i++)sum+=(a[i]-b[i]).sqrMagnitude;return Mathf.Sqrt(sum/a.Length);}
  static float ManipulateHat(RunwayPickup hat,MembraneMaterial material,bool compress){hat.ReturnToDisplay();hat.Elastic.SetSize(1);hat.Elastic.SetMaterial(material);hat.Elastic.ResetShape();var mesh=hat.Elastic.MeshAt(0);Vector3[] v=mesh.vertices;int left=0,right=0;for(int i=1;i<v.Length;i++){if(v[i].x<v[left].x)left=i;if(v[i].x>v[right].x)right=i;}Vector3 p0=hat.transform.TransformPoint(v[left]),p1=hat.transform.TransformPoint(v[right]);var target=hat.GetComponent<RunwayVRGrabTarget>();object a=new object(),b=new object();Check(target.TryAcquire(a,p0,Quaternion.identity)&&target.TryAcquire(b,p1,Quaternion.identity),"Two-hand hat grip failed");Check(hat.Elastic.GrabCount==2,"Two owners did not engage hat deformation");float sign=compress?-1:1;
   for(int i=0;i<90;i++){target.DragOwned(a,p0-Vector3.right*.07f*sign,Quaternion.identity);target.DragOwned(b,p1+Vector3.right*.07f*sign,Quaternion.identity);hat.Elastic.Step(1f/60);}
   float offset=hat.Elastic.MaximumOffset;if(compress){result.compression=hat.Elastic.Reading.compressiveStrain>.003f;Check(result.compression,"Pushing two hands inward did not compress material");}else{result.twoHandStretch=hat.Elastic.Reading.tensileStrain>.003f;Check(result.twoHandStretch,"Spreading hands did not stretch hat");}
   target.Release(a,false);Check(target.OwnerCount==1&&hat.IsHeld,"Releasing first hat hand dropped object");target.Release(b,true);Check(hat.GetComponent<Rigidbody>().useGravity,"Last release disabled hat gravity");hat.ReturnToDisplay();return offset;
  }
  static void Export(PoseWearable wearable,string name){var avatar=wearable.Rig.Avatar;var body=new Mesh();var original=avatar.Renderer.sharedMesh;avatar.Renderer.sharedMesh=avatar.BodyMesh;avatar.Renderer.BakeMesh(body);avatar.Renderer.sharedMesh=original;using(var w=new BinaryWriter(File.Create(folder+"/Contact/"+name+".bin"))){w.Write(0x53434631);Write(w,body.vertices,body.triangles);var mesh=wearable.Surface.MeshAt(0);Write(w,mesh.vertices,mesh.triangles);}UnityEngine.Object.DestroyImmediate(body);result.contactExports++;}
  static void Write(BinaryWriter w,Vector3[] p,int[] t){w.Write(p.Length);foreach(var v in p){w.Write(v.x);w.Write(v.y);w.Write(v.z);}w.Write(t.Length);foreach(int i in t)w.Write(i);}
  static void Capture(string name){var c=app.Player.View;c.rect=new Rect(0,0,1,1);c.transform.position=new Vector3(2.2f,1.55f,1.25f);c.transform.LookAt(new Vector3(2.2f,1,-1.9f));var rt=new RenderTexture(1400,1100,24);var tex=new Texture2D(1400,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1400,1100),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name,tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}}
  static void Cleanup(GameObject root){UnityEngine.Object.DestroyImmediate(root);}
 }
}
